// Step 1: Validate input envelope and parameters
const input = $input.first().json;

if (!input) {
  throw new Error('Empty envelope');
}

const correlationId = input.correlation_id || $execution.id;
const userId = input.user_id;
const payload = input.payload || {};
const text = payload.text || input.text;
const deliveryClass = payload.delivery_class || input.delivery_class || 'reactive';
const parseMode = payload.parse_mode || input.parse_mode || 'HTML';
const replyToMessageId = payload.reply_to_message_id || input.reply_to_message_id || null;

if (!userId) {
  return [{
    json: {
      ok: false,
      status: 'error',
      correlation_id: correlationId,
      error: {
        category: 'validation',
        code: 'MISSING_USER_ID',
        message_safe: 'user_id is required'
      }
    }
  }];
}

if (!text || text.trim() === '') {
  return [{
    json: {
      ok: false,
      status: 'error',
      correlation_id: correlationId,
      error: {
        category: 'validation',
        code: 'EMPTY_TEXT',
        message_safe: 'Message text cannot be empty'
      }
    }
  }];
}

const validClasses = ['reactive', 'proactive_normal', 'proactive_critical'];
if (!validClasses.includes(deliveryClass)) {
  return [{
    json: {
      ok: false,
      status: 'error',
      correlation_id: correlationId,
      error: {
        category: 'validation',
        code: 'INVALID_DELIVERY_CLASS',
        message_safe: `delivery_class must be one of: ${validClasses.join(', ')}`
      }
    }
  }];
}

return [{
  json: {
    correlation_id: correlationId,
    user_id: userId,
    text: text,
    delivery_class: deliveryClass,
    parse_mode: parseMode,
    reply_to_message_id: replyToMessageId,
    idempotency_context: payload.idempotency_context || null
  }
}];

const settings = $input.first().json;
const req = $('Validate Delivery Request').first().json;

if (!settings || !settings.authorized_telegram_chat_id) {
  return [{
    json: {
      ok: false,
      status: 'error',
      correlation_id: req.correlation_id,
      error: {
        category: 'authorization',
        code: 'NO_AUTHORIZED_TELEGRAM_CHAT',
        message_safe: 'No authorized Telegram chat configured for user'
      }
    }
  }];
}

const now = new Date();
const deliveryClass = req.delivery_class;
let canSend = true;
let suppressionReason = null;

if (deliveryClass === 'proactive_normal') {
  // Check rest mode
  if (settings.rest_mode_enabled) {
    if (!settings.rest_until || new Date(settings.rest_until) > now) {
      canSend = false;
      suppressionReason = 'rest_mode_active';
    }
  }
  // Check quiet hours
  if (canSend && settings.quiet_hours_enabled && settings.quiet_start_time && settings.quiet_end_time) {
    const currentTime = now.toTimeString().split(' ')[0];
    const start = settings.quiet_start_time;
    const end = settings.quiet_end_time;
    if (start < end) {
      if (currentTime >= start && currentTime <= end) {
        canSend = false;
        suppressionReason = 'quiet_hours_active';
      }
    } else {
      // Overnight range e.g. 22:00 to 07:00
      if (currentTime >= start || currentTime <= end) {
        canSend = false;
        suppressionReason = 'quiet_hours_active';
      }
    }
  }
} else if (deliveryClass === 'proactive_critical') {
  if (!settings.critical_can_break_silence) {
    if (settings.rest_mode_enabled || settings.quiet_hours_enabled) {
      canSend = false;
      suppressionReason = 'critical_cannot_break_silence';
    }
  }
}

return [{
  json: {
    ...req,
    chat_id: settings.authorized_telegram_chat_id,
    can_send: canSend,
    suppression_reason: suppressionReason
  }
}];

const tgRes = $input.first().json;
const req = $('Evaluate Silence and Rest Rules').first().json;

return [{
  json: {
    ok: true,
    status: 'completed',
    correlation_id: req.correlation_id,
    data: {
      delivered: true,
      provider_message_id: tgRes.message_id ? String(tgRes.message_id) : null,
      chat_id: req.chat_id,
      sent_at: new Date().toISOString()
    },
    warnings: []
  }
}];

const req = $input.first().json;

return [{
  json: {
    ok: true,
    status: 'suppressed',
    correlation_id: req.correlation_id,
    data: {
      delivered: false,
      suppressed: true,
      reason: req.suppression_reason
    },
    warnings: [`Message delivery suppressed due to ${req.suppression_reason}`]
  }
}];
